import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"en/roadmap.md","filePath":"en/roadmap.md","lastUpdated":null}'),i={name:"en/roadmap.md"};function r(l,e,s,d,c,m){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>The current version focuses on &quot;simple, robust, good enough&quot;. Planned capabilities, in priority order.</p><h2 id="near-term" tabindex="-1">Near term <a class="header-anchor" href="#near-term" aria-label="Permalink to &quot;Near term&quot;">​</a></h2><ul><li>[ ] <strong>Concurrent multi-connection</strong>: carry multiple local TCP connections over one tunnel simultaneously (currently sequential)</li><li>[ ] <strong>WebSocket signaling</strong>: instant guest-join notification to the host instead of polling (lower direct-link latency)</li><li>[ ] <strong>UPnP automatic port mapping</strong>: an additional option before punching, when the router supports it</li></ul><h2 id="mid-term" tabindex="-1">Mid term <a class="header-anchor" href="#mid-term" aria-label="Permalink to &quot;Mid term&quot;">​</a></h2><ul><li>[ ] <strong>x25519 key exchange</strong>: automatic per-session key agreement (replacing manual <code>--key</code>)</li><li>[ ] <strong>Encrypted relay</strong>: confidentiality on the relay path too (currently <code>--key</code> applies to P2P direct only)</li><li>[ ] <strong>Multi-node rooms (&gt;2 people)</strong>: a central node broadcasts member addresses for mesh P2P</li><li>[ ] <strong>Adaptive transport parameters</strong>: auto-tune window, retransmit interval, and MTU from loss/latency</li></ul><h2 id="long-term" tabindex="-1">Long term <a class="header-anchor" href="#long-term" aria-label="Permalink to &quot;Long term&quot;">​</a></h2><ul><li>[ ] <strong>Platform polish</strong>: Windows/macOS installers, autostart, tray icon</li><li>[ ] <strong>Relay cluster</strong>: multi-server relay pool with nearest routing</li><li>[ ] <strong>Compatibility layer</strong>: optional integration with existing protocol ecosystems</li></ul><h2 id="implemented-v0-1" tabindex="-1">Implemented (v0.1) <a class="header-anchor" href="#implemented-v0-1" aria-label="Permalink to &quot;Implemented (v0.1)&quot;">​</a></h2><ul><li>Room-based signaling (REST + UDP probe + TTL expiry)</li><li>UDP hole punching (PUNCH/ACK simultaneous handshake + port spread)</li><li>FRS1 reliable stream (sliding window + retransmit + keepalive + FIN handshake)</li><li>ChaCha20-Poly1305 end-to-end encryption (<code>--key</code>)</li><li>Sequential multi-connection reuse (<code>--max-conns</code>)</li><li>TCP relay fallback (pairing + bidirectional copy + late-direct re-check)</li><li>Windows compatibility (ICMP poisoning handling)</li><li>End-to-end tests and real-NAT verification</li></ul><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>PRs welcome. See <a href="./develop">Development &amp; Testing</a> and the <a href="./protocol">Protocol Spec</a>.</p>',12)])])}const h=t(i,[["render",r]]);export{u as __pageData,h as default};
